//! Crate-level name resolution for caller migration (V3-O04, MIGRATE-03).
//!
//! A generated setter call may only be rewritten after its receiver is proved
//! to be a type generated by one of the crate's `api!` declarations. The proof
//! follows paths the way the compiler resolves them, inside a bounded model of
//! the crate:
//!
//! * the module tree, from `mod` declarations (honoring `#[path]` on file and
//!   inline modules as rustc does), inline modules, the crate roots of the
//!   package (with the `path` entries of `Cargo.toml`) and, for files no
//!   crate root reaches, the file layout;
//! * the items, `use` imports (renames and globs) and generic parameters of
//!   every module and block, with their visibility (`pub`, `pub(crate)`,
//!   private, `pub(super)`, `pub(in path)`) evaluated from the looking module,
//!   so a local item, a generic parameter or an import shadows exactly as in
//!   Rust, a glob imports only what the importer may see, and `self::`,
//!   `super::` and `crate::` prefixes select exact modules;
//! * the items each `api!` invocation generates, placed at that invocation
//!   with the v2.1 names (`Client`, `ClientBuilder`, `client::scope::Scope`,
//!   `client::scope::EndpointRequest`, ...);
//! * struct fields and function return types, resolved in the scope that
//!   declares them, so a field is typed through its owning struct (only where
//!   the field is visible) and a call through the function the path actually
//!   names (an `async fn` call is an opaque future);
//! * standard wrappers (`Option`, `Result`, `Box`, `Arc`, `Rc`) and references
//!   around a type, kept as wrappers: an `Option<Client>` is not a `Client`;
//! * the trait and inherent `impl` blocks of the crate, with each trait path
//!   resolved to the trait it names, so a caller can tell whether a trait
//!   method may take precedence over a generated inherent method, and which
//!   methods users added to generated types;
//! * the origin of statement macros: only a macro whose path resolves to the
//!   standard library, `log` or `tracing` is known to introduce no binding;
//! * `#[cfg]`/`#[cfg_attr]`: a declaration gated by a predicate that is not
//!   trivially true (`all()`, `not(any())`) may not exist, so every name it
//!   defines, imports or shadows is *uncertain* (features are never
//!   evaluated);
//! * whether the crate's trait implementations (and, for the package's other
//!   targets, the library's) are completely visible (see
//!   [`CrateModel::incomplete`]) and which traits of other crates may be in
//!   scope at a place (see [`CrateModel::foreign_traits`]), so a call that
//!   reaches a generated method only after an auto-deref or auto-ref step is
//!   proved only when no trait the model cannot see may be selected first.
//!
//! Diagnostic reasons are deterministic: imports are walked in name order and
//! a crate's constructs in a fixed order.
//!
//! Whatever the model cannot see makes a name *unknown*: a module without a
//! source file, an item-position macro other than `api!` and the standard
//! ones, an attribute macro whose expansion is not known (see
//! [`CrateModel::unknown_attribute_macro`]), a derive other than the standard
//! ones and `serde`'s, a statement macro that does not resolve to a
//! known expression macro, an import whose path does not resolve, a glob from
//! another crate inside a block, or a declaration gated by `#[cfg]`. A path is
//! never resolved from its last segment alone.
//!
//! One resolution query memoizes every finished module lookup (unless it
//! depended on a lookup still in progress, see [`Lookup`]), so a graph of glob
//! re-exports is walked once per name instead of once per path.

use std::collections::{BTreeMap, HashMap, HashSet};
use std::fmt;
use std::path::{Path, PathBuf};

use proc_macro2::{TokenStream, TokenTree};
use quote::ToTokens;
use syn::punctuated::Punctuated;
use syn::visit::Visit;
use syn::{Expr, Item, Meta, Stmt, Token, Type};

use super::rust_file::{Imports, ParsedFile, SourceNamespace, bare_api_proof, is_concord_crate};

pub(crate) type ScopeId = usize;

/// Which generated surface a receiver is.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Role {
    /// The client builder (`ClientBuilder`).
    Builder,
    /// The built client (`Client`).
    Built,
    /// The root of the unbound endpoint tree (`client::Unbound`).
    Unbound,
    /// A bound scope facade (`client::scope::Scope`).
    Scope,
    /// An unbound scope (`client::scope::Unbound`).
    UnboundScope,
    /// A bound endpoint request (`client::EndpointRequest`).
    Request,
    /// An unbound endpoint intent (`client::Endpoint`).
    Endpoint,
}

/// One generated type: an owner of a declaration in a given role.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct OwnerRef {
    pub(crate) client: usize,
    pub(crate) owner: usize,
    pub(crate) role: Role,
}

/// The public items one `api!` invocation generates in its module.
pub(crate) struct GeneratedItems {
    /// The declaring client.
    pub(crate) client: usize,
    pub(crate) types: Vec<(String, OwnerRef)>,
    pub(crate) module: GeneratedModule,
}

/// A generated module and the public types it contains.
pub(crate) struct GeneratedModule {
    pub(crate) name: String,
    pub(crate) types: Vec<(String, OwnerRef)>,
    pub(crate) modules: Vec<GeneratedModule>,
}

/// A standard-library wrapper, or a reference, around a type.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Wrapper {
    Option,
    Result,
    Box,
    Arc,
    Rc,
    /// `&T`
    Ref,
    /// `&mut T`
    RefMut,
}

impl Wrapper {
    /// The wrapper a standard-library type name denotes.
    fn std(name: &str) -> Option<Self> {
        match name {
            "Option" => Some(Self::Option),
            "Result" => Some(Self::Result),
            "Box" => Some(Self::Box),
            "Arc" => Some(Self::Arc),
            "Rc" => Some(Self::Rc),
            _ => None,
        }
    }

    /// Whether `*` and method auto-deref reach the wrapped value (`Option`
    /// and `Result` implement no `Deref`).
    pub(crate) const fn derefs(self) -> bool {
        !matches!(self, Self::Option | Self::Result)
    }

    /// Whether a method taking the wrapped value by value can be called
    /// through auto-deref: only a `Box` can be moved out of.
    pub(crate) const fn moves_out(self) -> bool {
        matches!(self, Self::Box)
    }

    /// How the wrapper is written, for diagnostics.
    pub(crate) const fn spelling(self) -> &'static str {
        match self {
            Self::Option => "Option<_>",
            Self::Result => "Result<_, _>",
            Self::Box => "Box<_>",
            Self::Arc => "Arc<_>",
            Self::Rc => "Rc<_>",
            Self::Ref => "&_",
            Self::RefMut => "&mut _",
        }
    }
}

/// What a type (or the value of an expression) resolves to.
#[derive(Clone, Debug, PartialEq)]
pub(crate) enum TypeRes {
    /// Proved to be one or more generated types.
    Generated(Vec<OwnerRef>),
    /// A crate-local struct, proved by declaration identity.
    Struct(usize),
    /// A standard wrapper or reference around a generated type or a
    /// crate-local struct (built with [`TypeRes::wrap`]).
    Wrapped(Wrapper, Box<TypeRes>),
    /// A type of another crate, by its resolved path.
    External(Vec<String>),
    /// Proved not to be a type generated by this crate's declarations.
    Foreign,
    /// Not proved either way.
    Unknown,
}

impl TypeRes {
    /// `wrapper` around `inner`: a wrapper of a type that is not generated
    /// (and not a crate-local struct) is simply not generated.
    pub(crate) fn wrap(wrapper: Wrapper, inner: Self) -> Self {
        match inner {
            Self::Generated(_) | Self::Struct(_) | Self::Wrapped(..) => {
                Self::Wrapped(wrapper, Box::new(inner))
            }
            Self::Unknown => Self::Unknown,
            Self::External(_) | Self::Foreign => Self::Foreign,
        }
    }

    /// Whether two resolved types may be the same type (an unknown type may
    /// be any type).
    pub(crate) fn may_equal(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Unknown, _) | (_, Self::Unknown) => true,
            (Self::Generated(left), Self::Generated(right)) => {
                left.iter().any(|owner| right.contains(owner))
            }
            (Self::Wrapped(left, left_inner), Self::Wrapped(right, right_inner)) => {
                left == right && left_inner.may_equal(right_inner)
            }
            (Self::Struct(left), Self::Struct(right)) => left == right,
            (Self::External(left), Self::External(right)) => left == right,
            _ => false,
        }
    }
}

/// How a method takes its receiver.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum SelfKind {
    /// `self`
    Value,
    /// `&self`
    Ref,
    /// `&mut self`
    RefMut,
    /// `self: Type`, which may be any receiver type.
    Typed,
    /// No receiver: an associated function.
    Associated,
}

impl SelfKind {
    fn of(signature: &syn::Signature) -> Self {
        match signature.inputs.first() {
            Some(syn::FnArg::Receiver(receiver)) => match &receiver.kind {
                syn::ReceiverKind::Value => Self::Value,
                syn::ReceiverKind::Reference(_, _, Some(_)) => Self::RefMut,
                syn::ReceiverKind::Reference(_, _, None) => Self::Ref,
                // `self: Type`, and any receiver notation added later.
                _ => Self::Typed,
            },
            _ => Self::Associated,
        }
    }
}

/// How the last segment of a path is found in its scope or module.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Provenance {
    /// An item defined there (including an item an `api!` generates there).
    Item,
    /// An explicit `use` import (or `extern crate`).
    Import,
    /// A glob import.
    Glob,
    /// Not found, or hidden by something the model cannot see.
    Unknown,
}

/// Where a type or path is resolved.
#[derive(Clone, Copy)]
pub(crate) struct Context<'a> {
    /// The innermost lexical scope; `None` resolves nothing.
    pub(crate) scope: Option<ScopeId>,
    /// Generic type parameters in scope; they shadow every item name.
    pub(crate) generics: &'a [String],
    /// The `Self` type, inside an `impl`.
    pub(crate) self_type: Option<&'a TypeRes>,
}

/// The edition of a package, as far as `use` and `::` paths depend on it.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(crate) enum Edition {
    /// Edition 2015: `use` paths and `::` paths start at the crate root.
    Rust2015,
    /// Edition 2018 or later: `use` paths are relative (uniform paths) and
    /// `::name` names an extern crate.
    #[default]
    Rust2018OrLater,
    /// The manifest does not determine the edition (the reason why): a path
    /// whose meaning differs between the editions is unknown.
    Unknown(String),
}

/// How the files of one migration crate are organized.
#[derive(Clone, Debug, Default)]
pub(crate) struct Layout {
    /// The package directory (holding `Cargo.toml`), if any.
    pub(crate) package: Option<PathBuf>,
    /// The package library's extern crate name, if it has a library.
    pub(crate) library: Option<String>,
    /// The library's source file when `Cargo.toml` names one (`[lib] path`);
    /// otherwise `src/lib.rs`.
    pub(crate) library_path: Option<PathBuf>,
    /// Existing manifest authority for a genuine Concord own-library alias.
    pub(crate) concord_own: Option<String>,
    /// The source files of the `[[bin]]`, `[[test]]`, `[[example]]` and
    /// `[[bench]]` targets `Cargo.toml` names explicitly.
    pub(crate) target_paths: Vec<PathBuf>,
    /// The package's edition (`Rust2018OrLater` when no package applies).
    pub(crate) edition: Edition,
    /// The directory file paths are derived from when no package applies.
    pub(crate) base: PathBuf,
    /// A single file that forms its own crate.
    pub(crate) standalone: bool,
}

/// One parsed source file of the crate.
pub(crate) struct SourceFile<'a> {
    pub(crate) path: &'a Path,
    pub(crate) parsed: &'a ParsedFile,
    pub(crate) imports: &'a Imports,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum Entity {
    Scope(ScopeId),
    Generated(OwnerRef),
    Struct(usize),
    Alias(usize),
    Fn(usize),
    /// A crate-local trait (an index into [`CrateModel::traits`]).
    Trait(usize),
    /// Any other crate-local item (enum, union, const, static, ...).
    Local,
    External(Vec<String>),
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Ns {
    Type,
    Value,
}

#[derive(Clone)]
enum Res {
    Found(Vec<Entity>),
    NotFound,
    Unknown,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct UsePath {
    leading_colon: bool,
    segments: Vec<String>,
}

#[derive(Clone, Copy, Debug)]
enum ScopeKind {
    Module {
        parent: Option<ScopeId>,
        root: ScopeId,
    },
    Block {
        parent: ScopeId,
        module: ScopeId,
    },
}

#[derive(Default)]
struct Table {
    /// `(entity, visibility)` per name in the type namespace.
    types: HashMap<String, Vec<(Entity, Vis)>>,
    /// `(entity, visibility)` per name in the value namespace.
    values: HashMap<String, Vec<(Entity, Vis)>>,
    /// `(path, visibility)` per imported name (all namespaces), in name
    /// order (reasons found by walking them are deterministic).
    imports: BTreeMap<String, Vec<(UsePath, Vis)>>,
    /// `(path, visibility)` glob imports.
    globs: Vec<(UsePath, Vis)>,
    /// `(path, visibility)` of `use path as _;` imports (a trait in scope
    /// without a name).
    anonymous: Vec<(UsePath, Vis)>,
    /// Names with an entry whose visibility is `pub(super)` or
    /// `pub(in path)`, and whether a glob import has one: lookups of those
    /// depend on the exact module they are made from.
    restricted: HashSet<String>,
    restricted_globs: bool,
    /// Items this model cannot see may exist here: a name that is not found
    /// is unknown rather than absent.
    opaque: bool,
    /// Opacity from missing source/unknown attrs/derives, never API emissions.
    opaque_other: bool,
    /// A potential API's requested support namespaces, used only to deny
    /// self-shadowing. They supply no positive names or generated entities.
    pending_api_namespaces: HashSet<String>,
    pending_api_header_unknown: bool,
    /// Like `opaque`, because a macro invoked here (in item or statement
    /// position) may expand to items (kept apart so that macro's own name
    /// can still be resolved).
    expanded: bool,
    /// A source namespace may be introduced by an unknown expansion.
    namespace_expanded: bool,
    /// Names a `#[cfg]`/`#[cfg_attr]`-gated declaration (or an attribute
    /// macro) may define, import or shadow here: unknown.
    uncertain: HashSet<String>,
    /// A gated glob import: a name not defined or imported explicitly is
    /// unknown.
    uncertain_globs: bool,
}

struct Scope {
    kind: ScopeKind,
    table: Table,
}

struct StructDef {
    name: String,
    /// `(type, visibility)` per field name (a position for a tuple field).
    fields: HashMap<String, (Type, Vis)>,
    /// Named fields gated by `#[cfg]`/`#[cfg_attr]`.
    uncertain_fields: HashSet<String>,
    /// A gated positional field shifts every later index.
    positional_uncertain: bool,
    scope: ScopeId,
    generics: Vec<String>,
}

struct FnDef {
    name: String,
    /// An `async fn`: a call produces a future, not `output`.
    asyncness: bool,
    output: Option<Type>,
    scope: ScopeId,
    generics: Vec<String>,
}

struct AliasDef {
    ty: Type,
    scope: ScopeId,
    generics: Vec<String>,
}

/// One `impl` block of the crate.
struct ImplDef {
    self_ty: Type,
    scope: ScopeId,
    generics: Vec<String>,
    /// The implemented trait's path (`leading ::`, segments); `None` for an
    /// inherent impl.
    trait_path: Option<(bool, Vec<String>)>,
    methods: Vec<(String, SelfKind)>,
    /// `file.rs:line` of the `impl`, for diagnostics.
    location: String,
}

/// One trait of the crate.
struct TraitDef {
    name: String,
    /// Its methods (a default method is provided by every implementation).
    methods: Vec<(String, SelfKind)>,
    /// `file.rs:line` of its name, for diagnostics.
    location: String,
}

/// A trait implementation that may provide a method for some receiver type.
pub(crate) struct TraitReceiver {
    /// The receiver type of the method; `None` when the tool cannot bound it
    /// (a blanket implementation, an unresolved self type or a `self: Type`
    /// receiver).
    pub(crate) receiver: Option<TypeRes>,
    /// The trait as written in the `impl` (in backticks) and, when that name
    /// is an alias, the trait it resolves to, for diagnostics.
    pub(crate) trait_name: String,
    /// `file.rs:line` of the `impl`, for diagnostics.
    pub(crate) location: String,
    /// The trait is not defined in this crate, so its provided methods are
    /// unknown (any method name may be provided).
    pub(crate) foreign: bool,
    /// The `impl` is in the package library, not in the crate of the call.
    pub(crate) library: bool,
    /// When the `impl`'s self type does not resolve: that type as written
    /// and why, for diagnostics (it may be any probed type).
    pub(crate) unresolved_self: Option<String>,
}

/// A macro invocation, classified once the whole crate is collected.
struct MacroSite {
    scope: ScopeId,
    path: syn::Path,
    tokens: TokenStream,
    location: String,
}

/// A derive macro applied to an item, classified once the whole crate is
/// collected.
struct DeriveSite {
    scope: ScopeId,
    path: syn::Path,
    location: String,
}

/// Attributes that may be macros, classified once the whole crate is
/// collected (their paths resolve through its imports).
struct AttributeSite {
    scope: ScopeId,
    attributes: Vec<syn::Attribute>,
    kind: AttributeTarget,
    location: String,
}

/// What an [`AttributeSite`]'s attributes annotate.
enum AttributeTarget {
    /// A declaration of the site's scope defining these names: an unknown
    /// attribute macro may replace it and add items there.
    Item(Vec<String>),
    /// A member of an `impl` or `trait` body: it may add methods.
    Member,
    /// Anything else (a field, a parameter, a statement, ...).
    Other,
}

/// The name-resolution model of one crate.
#[derive(Default)]
pub(crate) struct CrateModel {
    scopes: Vec<Scope>,
    structs: Vec<StructDef>,
    fns: Vec<FnDef>,
    aliases: Vec<AliasDef>,
    impls: Vec<ImplDef>,
    /// The crate's traits.
    traits: Vec<TraitDef>,
    /// Names of the crate's `macro_rules!` macros (textual scope, which
    /// shadows every imported or prelude macro of the same name).
    macro_rules: HashSet<String>,
    /// The token streams of every `macro_rules!` definition, by name.
    macro_definitions: HashMap<String, Vec<TokenStream>>,
    /// Crate root -> the first construct found that may add trait
    /// implementations the model cannot see (see [`Self::incomplete`]).
    incomplete: HashMap<ScopeId, String>,
    /// Synthetic crate roots of the files no crate root reaches.
    synthetic: HashSet<ScopeId>,
    /// The module scope of each source file -> its file name.
    module_files: HashMap<ScopeId, String>,
    /// Crates imported with `#[macro_use] extern crate`.
    macro_use: Vec<String>,
    /// Generated support modules -> their client.
    supports: HashMap<ScopeId, usize>,
    /// Source path -> (file index, module scope), in path order.
    files: BTreeMap<PathBuf, (usize, ScopeId)>,
    /// `(file index, byte offset)` of an inline module name or a block's
    /// opening brace -> its scope.
    anchors: HashMap<(usize, usize), ScopeId>,
    /// The package library's extern name and crate root.
    library: Option<(String, ScopeId)>,
    /// Files mounted more than once (and the files of the modules they
    /// declare), by file index -> the other mount, for diagnostics. The model
    /// holds each file at its first mount only (see
    /// [`CrateModel::other_mount`]).
    mounts: HashMap<usize, String>,
    /// The package's edition: on edition 2015 `use` paths and `::` paths
    /// start at the crate root.
    edition: Edition,
}

impl fmt::Debug for CrateModel {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("CrateModel")
            .field("scopes", &self.scopes.len())
            .field("structs", &self.structs.len())
            .field("functions", &self.fns.len())
            .field("aliases", &self.aliases.len())
            .field("files", &self.files.len())
            .finish()
    }
}

